mapper.update:
update budget
dept_id = #{deptId}, period = #{period}, total_amount = #{totalAmount}, used_amount = #{usedAmount}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

update budget
set used_amount = used_amount + #{amount}
where dept_id = #{deptId}
  and period = #{period}
  and status = 1
  and total_amount - used_amount >= #{amount}

update budget
set used_amount = used_amount - #{amount}
where dept_id = #{deptId}
  and period = #{period}
  and used_amount >= #{amount}

mapper.select:
select b.id, b.dept_id, d.name as deptName, b.period, b.total_amount, b.used_amount, (b.total_amount - b.used_amount) as remainAmount from budget b left join department d on b.dept_id = d.id
and b.dept_id = #{deptId}
and b.period = #{period}
and b.status = #{status}
order by b.period desc, b.dept_id asc
